    s = l.strip()
    if s == '全国团体标准信息平' or s == '全国团体标准信息平台':
        continue
    if s == 'T/CSES 144-2024':
        continue
    # page number: pure digits right after footer (check previous raw line was a footer)
    if re.fullmatch(r'\d+', s):
        prev = raw_lines[i-1].strip() if i > 0 else ''
        if prev in ('全国团体标准信息平', '全国团体标准信息平台', 'T/CSES 144-2024'):
            continue
    lines.append(s)

def find(marker, start=0):
    for i in range(start, len(lines)):
        if marker in lines[i]:
            return i
    return -1

def parse_table(start_marker, end_marker, n_val, dept_set=None, fuel_set=None, tech_set=None, header_skip=1):
    start = find(start_marker)
    end = find(end_marker, start)
    body = lines[start+header_skip:end]
    rows = []
    i = 0
    while i < len(body):
        l = body[i]
        if dept_set is not None and l in dept_set:
            dept = l; i += 1
            fuel = body[i] if i < len(body) else None; i += 1
            tech = body[i] if i < len(body) else None; i += 1
            vals = []
            while i < len(body):
                if dept_set is not None and body[i] in dept_set:
                    break
                vals.append(body[i]); i += 1
            rows.append([dept, fuel, tech] + vals)
        else:
            i += 1
    return rows

# ---------------- D.1 ----------------
